  const shouldReduceMotion = useReducedMotion();
  const [visible, setVisible] = useState(isLoading);

  const handleFinish = useCallback(() => {
    if (onComplete) onComplete();
    if (onFinish) onFinish();
  }, [onComplete, onFinish]);

  useEffect(() => {
    if (!isLoading) {
      setVisible(false);
      return;
    }

    setVisible(true);
    // 2.2s total duration for calibrated Apple SMIL drawing + dwell
    const durationMs = shouldReduceMotion ? 150 : 2200;
    const timer = setTimeout(() => {
      handleFinish();
    }, durationMs);

    return () => clearTimeout(timer);
  }, [isLoading, shouldReduceMotion, handleFinish]);

